CREATE PROCEDURE [bud].[jsGetUserBudgetAllocation]  (      @userId  INT = 69,      @company INT = 1,      @month   VARCHAR(7) = '02-2026'   -- 'MM-YYYY'  )  AS  BEGIN      SET NOCOUNT ON;        ---------------------------------------------------------      -- 1️⃣ Convert Month      ---------------------------------------------------------      DECLARE @startDate DATE;      DECLARE @endDate   DATE;        SET @startDate =          DATEFROMPARTS(              CAST(RIGHT(@month,4) AS INT),              CAST(LEFT(@month,2)  AS INT),              1          );        SET @endDate = DATEADD(MONTH, 1, @startDate);          ---------------------------------------------------------      -- 2️⃣ Get All Active Queries For User      ---------------------------------------------------------      CREATE TABLE #UserQueries      (          queryText NVARCHAR(MAX)      );        INSERT INTO #UserQueries(queryText)      SELECT q.query      FROM jsuser u      JOIN jsuserstage us     ON u.userId = us.userId      JOIN jsStageTemplate st ON us.stageId = st.stageId      JOIN jsTemplate t       ON st.templateId = t.id      JOIN jsTemplateQuery tq ON t.id = tq.templateId      JOIN jsquery q          ON tq.queryId = q.id      WHERE          u.userId   = @userId          AND t.isActive = 1          AND q.type  = 5;        IF NOT EXISTS (SELECT 1 FROM #UserQueries)      BEGIN          RAISERROR('No active template queries found for this user.',16,1);          RETURN;      END          ---------------------------------------------------------      -- 3️⃣ Extract DISTINCT Budgets From Query Text      ---------------------------------------------------------      CREATE TABLE #UserBudgets      (          budgetName VARCHAR(200)      );        INSERT INTO #UserBudgets(budgetName)      SELECT DISTINCT             LTRIM(RTRIM(REPLACE(REPLACE(value,'''',''),'(','')))      FROM #UserQueries uq      CROSS APPLY      (          SELECT               SUBSTRING(                  uq.queryText,                  CHARINDEX('BUDGET IN', uq.queryText) + 10,                  CHARINDEX(')', uq.queryText, CHARINDEX('BUDGET IN', uq.queryText))                   - (CHARINDEX('BUDGET IN', uq.queryText) + 10)              ) AS BudgetList      ) AS Extracted      CROSS APPLY STRING_SPLIT(Extracted.BudgetList, ',')      WHERE uq.queryText LIKE '%BUDGET IN%';          ---------------------------------------------------------      -- 4️⃣ Allocation Aggregation (Month Filter Applied)      ---------------------------------------------------------      ;WITH Alloc AS      (          SELECT              subBudgetId,              SUM(allocatedAmount) AS AllocatedAmount          FROM bud.SubBudgetMonthlyAllocations          WHERE allocationMonth >= @startDate            AND allocationMonth <  @endDate          GROUP BY subBudgetId      )          ---------------------------------------------------------      -- 5️⃣ Final Result      ---------------------------------------------------------      SELECT          b.budgetName,          sb.subBudgetName,          ISNULL(a.AllocatedAmount, 0) AS AllocatedAmount      FROM (SELECT DISTINCT budgetName FROM #UserBudgets) ub      JOIN bud.Budgets b          ON b.budgetName = ub.budgetName      JOIN bud.SubBudgets sb          ON sb.budgetId = b.budgetId      LEFT JOIN Alloc a          ON a.subBudgetId = sb.subBudgetId      WHERE          b.company = @company          AND b.isActive = 1          AND sb.isActive = 1      ORDER BY          b.budgetName,          sb.subBudgetName;        ---------------------------------------------------------      -- Cleanup      ---------------------------------------------------------      DROP TABLE #UserQueries;      DROP TABLE #UserBudgets;    END
